"""Parity fixtures for the TS seller-variance AC7 bot (tests/seller-variance.test.ts), generated by running Economy's
Python reference, vendored and sha-pinned at vendor/economy-sim/sim/seller_variance_sim.py (source product/sim/) (seller-variance-proposal.md, sha256 17877b41).
Run from the repo root:  SV_SIM_DIR=<dir with seller_variance_sim.py> python3 scripts/gen-seller-variance-fixtures.py
(default SV_SIM_DIR = vendor/economy-sim/sim, the pinned in-repo copy; never product/ unless overridden).  -> tests/fixtures/seller_variance.json
Economy = this repo's data/economy.csv (M1 = P1Q formulas, workers = spec_from_csv), so TS and Python run the same numbers."""
import hashlib, json, os, sys
HERE = os.path.dirname(os.path.abspath(__file__)); ROOT = os.path.join(HERE, '..')
SIM = os.environ.get('SV_SIM_DIR', os.path.join(ROOT, 'vendor', 'economy-sim', 'sim'))
sys.path.insert(0, SIM)
import seller_variance_sim as S  # noqa: E402
CSV = os.path.join(ROOT, 'data', 'economy.csv')
import csv
ROWS = list(csv.DictReader(open(CSV)))
# Economy preset. P1Q formulas when they reproduce the CSV farm costs (main, pre-F1). Otherwise F1 (PR #17): farm_cost and
# w4_tier_cost are per-level tables read from this CSV, mirroring #17's balance.farm.costTable overrides (= S.F1, but from
# data/economy.csv instead of product/economy.f1-m4cols.csv). Every other M1 column must still match the P1Q formulas.
p1q = S.Eco(S.P1Q)
if all(p1q.fcost(int(r['level'])) == int(r['farm_cost']) for r in ROWS): PRESET, e = 'P1Q', p1q
else:
  PRESET = 'F1 (P1Q + farm_cost/w4_tier_cost tables from data/economy.csv)'
  e = S.Eco(dict(S.P1Q, name=PRESET, farm_cost_table={int(r['level']): int(float(r['farm_cost'])) for r in ROWS},
                 w4_cost_table={int(r['level']): int(float(r['w4_tier_cost'])) for r in ROWS}))
W = S.spec_from_csv(CSV)
# F1 merge: manage threshold from the CSV (run_m2 manage_at, default = tired_below)
W['manage_at'] = round(float(ROWS[0]['manage_prompt_threshold']) * 100); W['manage_all_low_only'] = True; W['wage_carry'] = True
# guard: the preset must reproduce data/economy.csv (otherwise the fixture compares different economies)
for r in ROWS:
  L = int(r['level']); assert e.fcost(L) == int(r['farm_cost']) and e.ccost(L) == int(r['collection_cost']), L
  assert abs(e.price(L) - float(r['egg_price'])) < 1e-9 and e.iv(L) == float(r['customer_interval_s']), L
SEEDS = list(range(1, 101)); T = 3600; TRACE_SEEDS = SEEDS[:5]; TRACE_N = 400
# Action trace: every variance-stream call in order. Its sequence is economy-independent (check-in/tap times, delay and
# cheap-first rolls depend only on the stream and the clock), so TS must reproduce it exactly even where coins differ.
TR = None
def _wrap(name, kind):
  f = getattr(S._V, name)
  def g(self, *a):
    v = f(self, *a)
    if TR is not None and self.v: TR['n'][kind] += 1; TR['sum'][kind] += float(v); (len(TR['seq']) < TRACE_N) and TR['seq'].append([kind, float(v)])
    return v
  setattr(S._V, name, g)
for nm, k in (('check', 'check'), ('tap', 'tap'), ('delay', 'delay'), ('cheap', 'cheap')): _wrap(nm, k)
def new_trace(): return dict(n=dict(check=0, tap=0, delay=0, cheap=0), sum=dict(check=0.0, tap=0.0, delay=0.0, cheap=0.0), seq=[])
traces = {}
def pack(r): return dict(reach={str(k): v for k, v in sorted(r['reach'].items())}, buys=len(r['buys']), c=r['c'], f=r['f'])
runs = {}
for wk in ('m1', 'm2'):
  for mode, var in (('old', None), ('variance', S.VAR_DEFAULT)):
    rs = {}
    for sd in SEEDS:
      TR = new_trace() if var and sd in TRACE_SEEDS else None
      rs[str(sd)] = pack(S.run(e, 'seller15', sd, T=T, var=var) if wk == 'm1' else S.run_m2(e, 'seller15', sd, T=T, spec=W, var=var))
      if TR: traces[f'{wk}/{mode}/{sd}'] = TR
      TR = None
    runs[f'{wk}/{mode}'] = rs
# raw variance-stream draws (exact): skill, then 40 interleaved check/tap/delay/cheap draws, seeds 0..3
draws = {}
for s in range(4):
  V = S._V(S.VAR_DEFAULT, s); d = []
  for _ in range(10): d += [V.check(15), V.tap(), float(V.r.random()), V.r.lognormvariate(0, 0.35)]
  draws[str(s)] = dict(skill=V.skill, seq=d)
sha = lambda p: hashlib.sha256(open(p, 'rb').read()).hexdigest()[:8]
out = dict(source='vendor/economy-sim/sim/seller_variance_sim.py (vendored from product/sim/) run/run_m2 policy=seller15', sim_sha256=sha(os.path.join(SIM, 'seller_variance_sim.py')),
           proposal_sha256=sha(os.path.join(SIM, 'seller-variance-proposal.md')), economy_csv_sha256=sha(CSV), config=PRESET + ' + spec_from_csv(data/economy.csv)',
           python=sys.version.split()[0], T=T, seeds=SEEDS, var=S.VAR_DEFAULT, draws=draws, traces=traces, runs=runs)
path = os.path.join(ROOT, 'tests', 'fixtures', 'seller_variance.json')
# compact: minified, one line per run/seed and per trace (diff-friendly)
J = lambda x: json.dumps(x, sort_keys=True, separators=(',', ':'))
def block(d, ind): return '{\n' + ',\n'.join(f'{ind}{J(k)}:{v}' for k, v in d.items()) + '\n' + ind[:-1] + '}'
body = {k: J(v) for k, v in out.items() if k not in ('runs', 'traces')}
body['traces'] = block({k: J(v) for k, v in out['traces'].items()}, '  ')
body['runs'] = block({k: block({sd: J(r) for sd, r in v.items()}, '   ') for k, v in out['runs'].items()}, '  ')
open(path, 'w').write(block(body, ' ') + '\n')
print('wrote', path)
